/**
 * Tracks whether readiness field values are user-confirmed vs autopilot-suggested.
 * Autopilot-seeded values must not inflate filing-readiness scores until confirmed.
 */
const DRAFT_SUGGESTED = 'draft_suggested';
const USER_CONFIRMED = 'user_confirmed';

const isDraftSuggested = (obj = {}) => obj?.confirmationStatus === DRAFT_SUGGESTED;

const isUserConfirmed = (obj = {}) => obj?.confirmationStatus === USER_CONFIRMED;

const markDraftSuggested = (obj = {}, suggestedBy = 'readiness_autopilot') => ({
  ...obj,
  confirmationStatus: DRAFT_SUGGESTED,
  suggestedBy,
  suggestedAt: new Date().toISOString()
});

const markUserConfirmed = (obj = {}, confirmedBy = 'user') => ({
  ...obj,
  confirmationStatus: USER_CONFIRMED,
  confirmedBy,
  confirmedAt: new Date().toISOString()
});

export {
  DRAFT_SUGGESTED,
  USER_CONFIRMED,
  isDraftSuggested,
  isUserConfirmed,
  markDraftSuggested,
  markUserConfirmed
};
